from rest_framework.decorators import api_view, permission_classes
from rest_framework.permissions import IsAuthenticated
from rest_framework.response import Response
from rest_framework import status
from django.contrib.auth import get_user_model
from hijack.helpers import login_user

User = get_user_model()

@api_view(['POST'])
@permission_classes([IsAuthenticated])
def initiate_support_impersonation(request, user_id: int):
    # Verify caller is a verified support staff member with hijack authorization
    if not request.user.is_staff or not request.user.has_perm('hijack.can_hijack'):
        return Response({'error': 'Unauthorized: Only authorized staff may initiate impersonation'}, status=status.HTTP_403_FORBIDDEN)

    try:
        target_user = User.objects.get(pk=user_id)
    except User.DoesNotExist:
        return Response({'error': 'User not found'}, status=status.HTTP_404_NOT_FOUND)

    if target_user.is_superuser:
        return Response({'error': 'Cannot impersonate superuser accounts'}, status=status.HTTP_403_FORBIDDEN)

    login_user(request, target_user)
    return Response({'status': 'impersonating', 'impersonated_user': target_user.username})
